// Package backgrounds lists the wallpapers that ship with HomeView.
//
// The images are original work generated by tools/backgrounds/gen.py, so they
// carry the project's own licence. Each one lives in
// internal/web/static/backgrounds as <id>.webp (1920x1080) and
// <id>-thumb.webp (480x270).
package backgrounds

// Default is what a user sees until they pick something else.
const Default = "oceano"

// Background is one bundled wallpaper.
type Background struct {
	ID string
}

// All is the display order.
var All = []Background{
	{"oceano"}, {"crepusculo"}, {"montanhas"}, {"floresta"}, {"dunas"}, {"malha-pastel"},
	{"poligonos"}, {"aurora"}, {"estrelas"}, {"topografico"}, {"grafite"},
}

// Valid reports whether id names a bundled wallpaper.
func Valid(id string) bool {
	for _, b := range All {
		if b.ID == id {
			return true
		}
	}
	return false
}

// URL is where the full-size image is served.
func URL(id string) string { return "/static/backgrounds/" + id + ".webp" }

// ThumbURL is where the thumbnail is served.
func ThumbURL(id string) string { return "/static/backgrounds/" + id + "-thumb.webp" }
